  Map<String,Object>s=db.one("SELECT s.response_id,s.review_state,s.risk_level,s.review_note,s.reviewer,s.reviewed_at,x.record_id,l.release_id,l.revision,l.document_json,f.score_json,f.ai_state,f.ai_output FROM a_questionnaire_responses s JOIN a_questionnaire_assignments x ON x.assignment_id=s.assignment_id AND x.scope_code=s.scope_code AND x.data_mode=s.data_mode JOIN a_questionnaire_releases l ON l.release_id=x.release_id AND l.scope_code=x.scope_code AND l.data_mode=x.data_mode JOIN a_questionnaire_processing f ON f.response_id=s.response_id WHERE s.response_id=? AND s.scope_code=? AND s.data_mode=? FOR UPDATE",r.get("response_id"),a.scope,a.mode);
