  Map<String,Object>order=(Map<String,Object>)orders.create(a,map("requestKey",stable(text(b,"requestKey")+":order"),"sourceWorker","care","targetWorker","plan","kind","psychological_plan","recordId",r.get("record_id"),"title","心理评估结果移交：请方案小谷制定管理方案","instructions",snapshot.get("concerns"),"priority",r.get("priority"),"dueAt",b.get("dueAt"),"payload",snapshot,"emergency",num(r.get("emergency"))==1,"dispatch",true));
  String hid=id();db.insert("a_psych_worker_handoffs",map("handoff_id",hid,"item_id",id,"scope_code",a.scope,"data_mode",a.mode,"record_id",r.get("record_id"),"worker_task_id",order.get("id"),"assessment_snapshot",ehr.encode(snapshot),"confirmed_by",a.user,"created_at",now(),"updated_at",now()));
  if(r.get("emergency_ack_by")!=null)db.exec("UPDATE a_worker_orders SET emergency_ack_by=? WHERE order_id=?",r.get("emergency_ack_by"),order.get("id"));
  event(a,id,str(r.get("record_id")),"assessment_handed_to_plan",map("handoffId",hid,"orderId",order.get("id")));return questionnaires.finish(a,b,map("id",hid,"orderId",order.get("id"),"state","submitted"));
