  db.exec("UPDATE a_psych_worker_handoffs SET handoff_state=?,feedback_json=?,received_by=?,received_at=COALESCE(received_at,UTC_TIMESTAMP(6)),row_version=row_version+1,updated_at=UTC_TIMESTAMP(6) WHERE handoff_id=?",state,ehr.encode(data),a.user,hid);event(a,str(h.get("item_id")),str(h.get("record_id")),"plan_feedback_received",data);
